      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Thor says he killed the giant Thjazi and hurled the eyes of Alvaldi's son up into the hot heavens as visible marks of his deeds.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "Harbarth says he worked 'love-craft' with night-riders, stole them from their husbands, received a wand as a gift from Hlebarth, and stole Hlebarth's wits away.",
