      "evidence_refs": [
        "ev:10"
      ]
    },
    {
      "id": "obs:11",
      "text": "Harbarth offers that a ring for Thor's hand will make things right, as a judge decides who sets the two at peace.",
      "category": "speech",
      "evidence_refs": [
        "ev:11"
      ]
    },
    {
      "id": "obs:12",
      "text": "Harbarth says he learned his scornful speech from very old men who dwell in the hills of home; Thor mocks this as calling heaps of stones 'hills of home.'",
      "category": "speech",
      "evidence_refs": [
        "ev:12"
      ]
