      "id": "obs:13",
      "text": "Thor threatens to wade the water and says Harbarth would cry loudly if struck by Thor's hammer.",
      "category": "speech",
      "evidence_refs": [
        "ev:13"
      ]
    },
    {
      "id": "obs:14",
      "text": "Harbarth claims Sif has a lover at home whom Thor should meet, and Thor calls this a lie.",
      "category": "speech",
      "evidence_refs": [
        "ev:14"
      ]
    },
    {
      "id": "obs:15",
      "text": "Thor orders the ferryman to row the boat over and take 'Magni's father' across; Harbarth refuses and says Thor has not the passage.",
