      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:12",
      "text": "Othin instructs Vithar to let \"the wolf's father\" find a seat at the feast to prevent Loki from speaking evil in Ægir's hall; Vithar rises and pours drink for Loki.",
