  "canonical_text": {
    "quote": "",
    "summary": "Editorial notes discuss manuscript order problems and variant traditions concerning Sigurth, Gripir, Gunnar, Brynhild, and Guthrun. Topics include three nights of sleeping with a sword between Sigurth and Brynhild while Sigurth is in Gunnar’s form; differing accounts of the order of marriages; an oath remembered by Sigurth; a quarrel at a bath where Guthrun claims Sigurth (not Gunnar) rode through flames; Brynhild’s accusation of oath-violation leading to Sigurth’s death; a variant where Sigurth and Brynhild have a daughter (Aslaug) left with Heimir; and identification of Gotthorm as Gunnar’s half-brother and Sigurth’s slayer.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "The notes state that the manuscript order of stanzas is 41, 43, 42, and editors differ on how to arrange them; Sigurth’s question in stanza 42 refers to three nights not previously mentioned by Gripir.",
      "category": "other",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "A suggested reconstruction describes Sigurth sleeping three nights with a sword between himself and Brynhild, and later poems describe Sigurth laying his sword Gram between them.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:3",
      "text": "The notes state that simultaneous weddings of Sigurth and Gunnar are a feature of the German tradition (as in the Nibelungenlied), while the Volsungasaga has Sigurth marry Guthrun before going with Gunnar to win Brynhild.",
      "category": "sequence",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:4",
