      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:3",
      "text": "The introductory note states the poem drew on prose and verse material, other Eddic poems, lost poems, and prose traditions; it mentions Oddrunargratr and the figure Oddrun as late additions and proposes a composition date in the late eleventh or early twelfth century.",
      "category": "other",
      "evidence_refs": [
        "ev:2"
