  "canonical_text": {
    "quote": "",
    "summary": "Editorial notes identify principal figures (Gjuki and his children, Sigurth, Brynhild, Atli, Gotthorm) and summarize variant traditions: Sigurth goes to the Gjukungs after slaying the dragon Fafnir; an oath/blood-brotherhood binds Sigurth with Gunnar and Hogni; Brynhild is won through deception involving Sigurth in Gunnar’s shape; Brynhild later discovers the deceit and in one strand had loved Sigurth from the outset; Brynhild is associated with the killing of Sigurth and Guthrun’s young son Sigmund; Sigurth’s wealth/treasure is linked to the Rhine and greed for it is cited as a motive for his slaying; the notes also mention a glacier as local color and discuss possible extra brothers and manuscript interpolations.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Gjuki is identified as father of Gunnar, Hogni, and Guthrun.",
      "category": "relationship",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Sigurth goes to the home of the Gjukungs after his victory over the dragon Fafnir (in this version), without meeting Brynhild on the way.",
      "category": "sequence",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "An oath/blood-brotherhood is mentioned as sworn by Sigurth, Gunnar, and Hogni.",
      "category": "action",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "Brynhild is described as being won by Sigurth while Sigurth is in Gunnar’s shape, and the poet omits details while hinting at a different tradition later in the poem.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "One summarized variant says Brynhild lived happily as Gunnar’s wife until a quarrel with Guthrun revealed the deceit by which she had been won.",
      "category": "sequence",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:6",
      "text": "Another summarized variant says Brynhild lived happily with Atli (her brother) until he was attacked by Gunnar and Sigurth, and she was compelled to marry Gunnar; her consent was obtained by representing Gunnar as Sigurth.",
      "category": "sequence",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:7",
      "text": "Brynhild is said to have discovered the deceit practiced on her; the note discusses whether she had loved Sigurth from the outset and how this fits different story versions.",
      "category": "attribute",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:8",
      "text": "A glacier is noted as Icelandic (or Greenland) local color.",
      "category": "setting",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:9",
      "text": "Sigmund is identified as the three-year-old son of Sigurth and Guthrun, killed at Brynhild’s behest.",
      "category": "action",
      "evidence_refs": [
        "ev:9"
      ]
    },
    {
      "id": "obs:10",
      "text": "The Rhine is connected with gold-bearing sands and is presented as an original home of the Nibelungs’ treasure; greed for Sigurth’s wealth is indicated as a motive for his slaying, also found in German versions of the story.",
      "category": "other",
      "evidence_refs": [
        "ev:10"
      ]
    },
    {
      "id": "obs:11",
      "text": "Gotthorm is identified as a half-brother of Gunnar and Hogni; the notes discuss possible traditions about the number of Gjuki’s sons (four or five).",
      "category": "relationship",
      "evidence_refs": [
        "ev:11"
      ]
    }
