      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:9",
      "text": "They see Atli’s halls and high watch-towers; warriors of Buthli stand on the lofty walls; the hall is surrounded with seats and decorated with targets and bright shields.",
      "category": "setting",
      "evidence_refs": [
        "ev:9"
