  "canonical_text": {
    "quote": "",
    "summary": "Gunnar shows proof that Hogni is dead and declares that the Niflungs' treasure will be hidden in the Rhine rather than fall to Atli. Gunnar is taken to death and cast into a serpent-den, where he plays a harp. Atli returns home; Guthrun offers him drink and food, then declares that he has eaten the hearts and flesh of his own sons. She distributes gold, then takes vengeance by loosing hounds, waking thralls, and setting the hall on fire, burning those within; the passage ends by praising her as an unmatched avenger of her brothers.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Gunnar presents a heart said to be Hogni's and contrasts it with Hjalli's heart, describing its lack of trembling on a platter and in the breast.",
      "category": "object",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Gunnar says the secret of the Niflungs' hoard is known only to him now that Hogni is dead, whereas formerly two people knew it.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "Gunnar says the Rhine will hold the Niflungs' gold in the depths of the waters so it will not shine on the hands of the Hunnish men.",
      "category": "setting",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "Atli orders that a wagon be brought because someone is now bound.",
