      "evidence_refs": [
        "ev:10"
      ]
    },
    {
      "id": "obs:12",
      "text": "The arrivals are treated kindly with ale and kindled fires; gifts are taken and hung on pillars; the hosts do not fear craft from the guests.",
      "category": "action",
      "evidence_refs": [
