      ]
    },
    {
      "id": "obs:3",
      "text": "Vingi is struck with axes and killed.",
      "category": "action",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "Atli summons armed men in mail-coats; there is fighting outside the hall with bows and shields.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "Guthrun hears of the fight, flings off necklaces and silver rings, opens the doors, and goes to the Niflungs to speak and give a last greeting.",
      "category": "action",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:6",
      "text": "Guthrun warns for safety that they should have stayed home, says none escapes fate, then grasps a naked sword to guard her kin and strikes down two warriors, including Atli's brother.",
      "category": "action",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:7",
      "text": "The battle is described as famous; the field flows with blood; eighteen foes are said to have been slain before the Niflungs fall.",
      "category": "setting",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:8",
      "text": "Atli (or a warrior speaking in anger) counts the reduction of his men and brothers, says his gold is robbed, and laments that a wife brought slaughter, including sending his sister to hell.",
      "category": "speech",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:9",
      "text": "Guthrun tells Atli that he committed earlier evils: taking her mother and murdering her for gold, and starving her sister's daughter in a prison.",
      "category": "speech",
      "evidence_refs": [
        "ev:9"
      ]
    },
    {
      "id": "obs:10",
      "text": "Atli orders Hogni seized and his heart cut out; he orders Gunnar bound on a gallows and cast to serpents; Hogni says he will await it bravely.",
      "category": "speech",
      "evidence_refs": [
        "ev:10"
      ]
    },
    {
      "id": "obs:11",
      "text": "Beiti (Atli's steward) proposes seizing Hjalli and sparing Hogni; Hjalli, a frightened cook/pot-watcher, flees and begs not to die; they seize the cook with a knife and he offers to do menial work if spared.",
