      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:6",
      "text": "Guthrun refuses Atli’s gifts and says he can never make amends for her brothers’ murder.",
      "category": "speech",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:7",
      "text": "Guthrun describes her childhood with her brothers in one house and says Grimhild gave them gold and necklaces.",
