      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:8",
      "text": "Guthrun uses tree imagery (tree-top bows low without leaves; tree bends if roots are cleft) while addressing Atli’s rule.",
      "category": "speech",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:9",
      "text": "Atli trusts Guthrun; Guthrun speaks craftily and makes her glance pleasant as part of her guile.",
      "category": "attribute",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:10",
      "text": "Guthrun brings beer for her brothers’ death-feast, and Atli makes a feast; the mead is prepared and men gather with uproar.",
      "category": "sequence",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:11",
      "text": "Guthrun calls the little ones, lays them on a block, and states she will murder them; she kills both boys and cuts off their heads.",
