      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:13",
      "text": "Guthrun tells Atli he has lost both his sons, and says he used their skulls as beer-cups and drank a draught mixed with their blood.",
      "category": "speech",
      "evidence_refs": [
        "ev:7"
      ]
