  "canonical_text": {
    "quote": "",
    "summary": "Minchihr’s astrologers determine that his death is near and advise preparation. Minchihr summons his courtiers, counsels his son Nauder against attachment to worldly power, recounts his deeds and guidance from Feridun, and resigns the kingdom to Nauder. He urges continued worship of God and adherence to the worship taught by Moses, warns of a future invasion from the mountains led by Turan son of Poshang, and advises seeking aid from Sam and Zal (and a “young branch just blossoming”). Soon after delivering this exhortation, Minchihr dies.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Astrologers ascertain that Minchihr’s time of death is at hand and advise him to complete necessary actions before death.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Minchihr calls his courtiers and gives counsel to his son Nauder about the fleeting nature of the world and kingship.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "Minchihr recounts that he followed Feridun’s commands and advice, punished Salm and Tur for killing Irij, built cities, and made a poisonous tree yield wholesome fruit.",
      "category": "sequence",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "Minchihr resigns the kingdom to Nauder and frames it as the kingdom that belonged to Feridun.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "Minchihr instructs Nauder not to turn from worship of God and describes Moses as teaching sacred worship.",
      "category": "speech",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:6",
      "text": "Minchihr predicts peril: an enemy will come from the wild mountains led by Turan son of Poshang, and advises seeking aid from Sam and Zal and a “young branch just blossoming.”",
      "category": "speech",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:7",
      "text": "Minchihr uses a caravan traveling to another city as a metaphor for his own destined journey toward death.",
      "category": "speech",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:8",
      "text": "After this exhortation, Minchihr, though initially free from illness, shortly closes his eyes in death.",
      "category": "action",
      "evidence_refs": [
        "ev:8"
      ]
    }
  ],
