      "category": "speech",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "Ks resolves to test Saiwush's innocence by an ordeal of fire; a large fire is lit on a plain; Saiwush, wearing a golden helmet and white robe, rides a black horse, prays to the Almighty, and enters the flames.",
      "category": "sequence",
      "evidence_refs": [
