  "canonical_text": {
    "quote": "",
    "summary": "Fermurz, equipped in Rustem’s armor and mounted on Rustem’s horse, fights and captures Barz with a noose. Kai-khosru spares Barz at Rustem’s request. Barz’s mother Shh-r bribes a singing-girl in Rustem’s household to smuggle a ring and then a file to Barz so he can break his chains and escape with three prepared horses. Rustem later encounters the fugitives while hunting, attempts to poison Barz via food, but Barz’s mother warns him and the singing-girl eats and dies; Barz condemns Rustem’s treachery.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Fermurz is dressed in Rustem’s armor, given Rustem’s weapons, and mounted on Rustem’s horse Rakush to present himself to Barz as the warrior from the previous day.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Fermurz shoots an arrow at Barz and claims to be his adversary; Barz notices differences in voice and action despite the same armor and horse, and questions whether the prior opponent is wounded or dead.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "Fermurz gives the name “Rustem” when asked and describes himself as descended from warriors who shed the blood of heroes.",
      "category": "speech",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "Fermurz attacks Barz, strikes him with a battle-axe, and captures him using a noose; he chooses to take Barz alive as a captive.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "Afrsiyb advances with his army to rescue Barz; Kai-khosru and Rustem support Fermurz, and Rustem throws an additional noose around Barz’s neck to prevent escape; the armies fight until dark.",
      "category": "sequence",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:6",
      "text": "Prn-wsah advises retreat across the Jihn, and Afrsiyb withdraws with his troops from Persia.",
      "category": "action",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:7",
      "text": "Kai-khosru orders Barz executed, but Rustem asks that Barz be spared due to his youth and sent to Sstn; the request is granted.",
      "category": "action",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:8",
      "text": "Barz’s mother Shh-r travels to Irn and then to Sstn and enlists a singing-girl employed by Rustem by giving her presents and requesting help.",
      "category": "action",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:9",
      "text": "The singing-girl secretly sends Barz food with a ring concealed inside to notify him that his mother is nearby; Barz asks for a large file to free himself from chains.",
      "category": "action",
      "evidence_refs": [
        "ev:9"
      ]
    },
    {
      "id": "obs:10",
      "text": "A file is delivered, three fleet horses are prepared under the walls, and Barz escapes at night with his mother and the singing-girl toward Trn.",
      "category": "action",
      "evidence_refs": [
        "ev:10"
      ]
    },
    {
      "id": "obs:11",
      "text": "Rustem meets the fugitives while hunting; after fighting and resting, Barz says the Almighty freed him and identifies the two women as his mother and a singing-girl from Rustem’s household.",
      "category": "speech",
      "evidence_refs": [
        "ev:11"
      ]
    },
    {
      "id": "obs:12",
      "text": "Rustem decides to poison Barz by mixing a deleterious substance into food; Barz’s mother warns him, Barz refrains, but the singing-girl eats and dies immediately; Barz reproaches Rustem for treachery.",
      "category": "sequence",
      "evidence_refs": [
        "ev:12"
      ]
    }
