      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Kai-khosru dismounts from an elephant, mounts a horse, and prepares to fight, but his warriors seize the bridle to prevent him.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
