      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:5",
      "text": "Gushtsp advises Ahrun to bring a dagger and fasten a number of knives around it; the weapon is later mounted on a spear and thrust down the dragon’s throat.",
