  "canonical_text": {
    "quote": "",
    "summary": "Isfendiyr continues a perilous journey guided by the demon Kurugsar. The guide’s earlier warnings about burning sand and lack of water are undermined by snow-cooled ground and a great river; Kurugsar admits he exaggerated dangers because he resented being kept in chains. Isfendiyr frees him and promises him a kingdom, and Kurugsar leads the party safely across the river. Near the Brazen Fortress, Kurugsar angrily curses Isfendiyr’s violent intentions; Isfendiyr kills him with a single sword-stroke. At night Isfendiyr secretly reconnoiters the Brazen Fortress and finds it an immense, seemingly impregnable structure of iron and brass with no accessible point for attack.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Isfendiyr’s soldiers declare they are ready to sacrifice their lives in his service and follow him.",
      "category": "speech",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Isfendiyr keeps Kurugsar in chains and continues toward a place described as covered with burning sand, but the sand is not hot due to heavy snow that has cooled the ground.",
      "category": "sequence",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "The demon-guide says the cooled sand is proof that Isfendiyr is under the protection of the Almighty; Isfendiyr accuses him of insincerity and deception.",
      "category": "speech",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "They come to a great river; Isfendiyr confronts Kurugsar for claiming there would be no water for forty farsangs.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "Kurugsar confesses he exaggerated the last day’s dangers to induce Isfendiyr to return and release him from bonds, because he felt scorned and kept in irons despite earlier correct guidance.",
      "category": "speech",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:6",
      "text": "Isfendiyr removes the irons from Kurugsar, treats him with kindness, and promises to reward him with the government of a kingdom after victory.",
      "category": "action",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:7",
      "text": "Kurugsar agrees to take the party safely across the river, and does so; the Brazen Fortress is then not far away.",
      "category": "sequence",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:8",
      "text": "Isfendiyr rests one farsang from the towers and asks Kurugsar for counsel about the fortress; Kurugsar calls it unimaginably strong and impregnable.",
      "category": "speech",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:9",
      "text": "Isfendiyr speaks of getting to Arjsp, cleaving the oppressor, defeating heroes, and leading wives and children captive to Iran.",
      "category": "speech",
      "evidence_refs": [
        "ev:9"
      ]
    },
    {
      "id": "obs:10",
      "text": "Kurugsar replies with a curse wishing calamity, sorrow, and death for Isfendiyr; Isfendiyr kills Kurugsar with one stroke, cleaving him in two.",
      "category": "action",
      "evidence_refs": [
        "ev:10"
      ]
    },
    {
      "id": "obs:11",
      "text": "At night Isfendiyr and some warriors secretly explore the Brazen Fortress and find it made of iron and brass, extremely tall and wide, with no accessible point for attack.",
      "category": "setting",
      "evidence_refs": [
        "ev:11"
      ]
    }
