  "canonical_text": {
    "quote": "",
    "summary": "Isfendiyr confronts Rustem and insists on taking him to the king in fetters, rejecting offers of wealth and hospitality. They fight; Rustem prays to God to direct his arrow, then shoots Isfendiyr in the eyes with a charmed arrow, blinding and fatally wounding him. Isfendiyr is treated and carried to his tent, then speaks of fate, sends messages to his parents, and dies; his body is borne on a bier to Iran. Rustem and Zl lament; Zl reports a prophecy that Isfendiyr’s slayer will soon meet a fatal end. Before dying, Isfendiyr entrusts his son Bahman to Rustem for guardianship and instruction; later Zra warns Rustem that raising the son of the slain enemy may lead to vengeance, but Rustem insists the guardianship is Heaven’s determination.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Isfendiyr claims Rustem’s prior wounds (from Isfendiyr’s arrows) have vanished and attributes the healing to sorcery by Rustem’s father Zl.",
      "category": "speech",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Rustem invites Isfendiyr to be his guest and offers to go to Isfendiyr’s father, but insists on going unfettered; Isfendiyr demands fetters.",
      "category": "sequence",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "Rustem offers jewels, diadems, damsels, and family wealth; Isfendiyr refuses, stating he must obey the king’s commands and bring Rustem in fetters to gain the crown and throne.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:4",
      "text": "Rustem places a forked arrow on his bow, prays to God to direct it into Isfendiyr’s eyes, and then shoots Isfendiyr in the eyes with a charmed weapon after dodging Isfendiyr’s shot.",
      "category": "action",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:5",
      "text": "Isfendiyr is blinded, collapses, and is carried to his tent after medicine is applied; his son Bahman laments and Bashtan and troops approach in sorrow.",
      "category": "sequence",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:6",
      "text": "Zl rejoices at the outcome but says astrologers and wise men have foretold that Isfendiyr’s slayer will soon die; Rustem says he is guiltless.",
      "category": "speech",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:7",
      "text": "Isfendiyr attributes his misfortune to an all-ruling power and fate, entrusts his son Bahman to Rustem for guardianship and instruction in governance and warfare, and states he has little time to live.",
      "category": "speech",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:8",
      "text": "Isfendiyr asks that his father be told the desired doom has been sealed and that his mother be informed gently; he dies and is conveyed on a bier to Iran amid public lamentation.",
      "category": "sequence",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:9",
      "text": "Rustem takes charge of Bahman and brings him to Sstn; Zra warns that the son may seek vengeance, but Rustem says the guardianship was entrusted with Isfendiyr’s last breath and is determined by Heaven.",
      "category": "speech",
      "evidence_refs": [
        "ev:8"
      ]
    }
