      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Rustem says he wants the bow so that, after death, he will appear like a scarecrow to keep wolves and other wild animals from devouring his body.",
      "category": "speech",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:3",
      "text": "Shughad strings the bow and places it before Rustem, apparently rejoicing at Rustem's impending death.",
