      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:4",
      "text": "Shughad hides behind a tree; Rustem shoots an arrow that pierces both the tree and Shughad, transfixing them together.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:5",
      "text": "Rustem lifts his eyes to Heaven, thanks the great Creator for granting him power to take revenge on his murderer, and then dies.",
      "category": "sequence",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:6",
      "text": "Other followers (including Zra) have sunk and perished in other pits dug by a traitor-king and a traitor-brother; one survivor flees and reports the news to a veteran at Sistan.",
