      ]
    },
    {
      "id": "obs:3",
      "text": "Dr refuses Sikander’s invitation to come before him, despite advice from nobles, and seeks assistance from Far of Ind; Sikander arranges for Dr to be intercepted.",
      "category": "sequence",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:4",
      "text": "Dr’s ministers Mahiyr and Jamsipr, citing astrologers’ predictions that Dr will soon fall into Sikander’s hands, decide to kill him to gain favor; they stab him at night while traveling.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:5",
      "text": "Sikander comes to the wounded Dr, weeps, offers to move him to safety and treat him, and vows punishment for the murderers; Sikander also asserts that he and Dr are sons of the same father.",
      "category": "speech",
      "evidence_refs": [
