      ]
    },
    {
      "id": "obs:6",
      "text": "Dr requests that Sikander preserve the honor of Dr’s family, marry Dr’s daughter Roshung, and, if blessed with a son, name him Isfendiyr; Dr links this to propagating Zerdusht’s sacred doctrines (Zendavesta), keeping the Nu-rz festival, and lighting the Holy Fire at the altar.",
      "category": "speech",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:7",
      "text": "After Sikander promises to fulfill Dr’s wishes, Dr places Sikander’s palm on his mouth and soon dies; Dr’s body is placed on a golden couch and taken to the grave.",
      "category": "sequence",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:8",
      "text": "Mahiyr and Jamsipr are executed near Dr’s tomb on the dar.",
