  "canonical_text": {
    "quote": "",
    "summary": "Sikander climbs a mountain known for seekers of knowledge and finds the jeweled corpse of an old saint. A voice prophesies his great conquests but warns that his death is near. Sikander weeps and descends. Later in Kashn he falls sick and dies as foretold, and companions and family mourn him for forty days.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Sikander ascends a mountain, resting often, and reaches the summit.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "On the summit appears the dead corpse of an old saint, wrapped in grave-clothes and embedded in gems, with gold and precious jewels glittering around.",
      "category": "object",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:3",
      "text": "The text states that none go upon that mountain top except to seek knowledge; Sikander hopes to see visions of futurity arise from the departed holy man.",
      "category": "sequence",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:4",
      "text": "A voice speaks, saying Sikander's time is near but it can unfold his earthly career: he will conquer many realms, win crowns, have many friends and foes, and be renowned, yet his time is near.",
      "category": "speech",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:5",
      "text": "Sikander weeps at the prophetic words and hastens down from the mountain.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:6",
      "text": "Afterward Sikander journeys to the city of Kashn, falls sick, and within a few days expires according to the oracle and prophecy.",
      "category": "action",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:7",
      "text": "Arist and Bilniys the physician, and his family, enter Kashn and find Sikander dead; they beat their faces, tear their hair, and mourn for forty days.",
      "category": "action",
      "evidence_refs": [
        "ev:6"
      ]
    }
